import re
from typing import List

def tokenize(expr: str) -> List[str]:
    """Convert expression string into a list of tokens"""
    # Pattern to match numbers (including negative), operators, and parentheses
    pattern = r'\s*(\d+|[+\-*/()]|\([^)]*\))'
    matches = re.findall(pattern, expr.replace(' ', ''))

    tokens = []
    for match in matches:
        if match in ['+', '-', '*', '/', '(', ')']:
            # Handle unary minus (negation at start or after operator)
            if match == '-' and not tokens or tokens[-1] in ['(', '+', '-']:
                tokens.append(match)
            else:
                tokens.append(match)
        elif re.match(r'\d+', match):
            tokens.append(match)
    return tokens

def parse_expressions(tokens: List[str]) -> int:
    """Parse expressions with + and - operators (lowest precedence)"""
    pos = [0]  # Using list to allow modification in closure

    def peek():
        if pos[0] < len(tokens):
            return tokens[pos[0]]
        return None

    def advance():
        if pos[0] < len(tokens):
            val = tokens[pos[0]]
            pos[0] += 1
            return val
        return None

    # Parse primary expression (handles *, /, (), and unary -)
    def parse_primary():
        token = peek()

        if token is None:
            raise ValueError("Unexpected end of expression")

        if token == '(':
            advance()  # consume '('
            result = parse_expressions(tokens)
            if peek() != ')':
                raise ValueError("Expected ')' after expression")
            advance()  # consume ')'
            return result

        elif token == '-':
            advance()  # consume '-'
            # Recursively parse the unary minus as a subtraction from 0
            return -parse_primary()

        elif token in ['+', '*']:
            raise ValueError(f"Unexpected operator '{token}' in primary")

        elif re.match(r'\d+$', token):
            advance()
            return int(token)

        else:
            raise ValueError(f"Unknown token '{token}'")

    # Parse terms with * and / (higher precedence than + and -)
    def parse_terms():
        left = parse_primary()

        while peek() in ['*', '/']:
            op = advance()
            right = parse_primary()

            if op == '*':
                left = left * right
            elif op == '/':
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                left = left / right

        return left

    # Parse factors with + and - (lowest precedence)
    def parse_factors():
        result = parse_terms()

        while peek() in ['+', '-']:
            op = advance()
            right = parse_terms()

            if op == '+':
                result = result + right
            elif op == '-':
                result = result - right

        return result

    # Call to start parsing from lowest precedence operators
    return parse_factors()

def eval_expression(expr: str) -> int:
    """Evaluate a mathematical expression with proper order of operations"""
    if not expr or not isinstance(expr, str):
        raise ValueError("Expression must be a non-empty string")

    tokens = tokenize(expr)
    result = parse_expressions(tokens)
    return result

# Test cases
if __name__ == "__main__":
    print(eval_expression("3 + 4 * (2 - 1)"))   # Expected: 7
    print(eval_expression("10 / 2"))            # Expected: 5.0
    print(eval_expression("-5 + 3"))             # Expected: -2
    print(eval_expression("(3 + 4) * 2"))        # Expected: 14
    print(eval_expression("-(2 + 3 * (4 - 1))")) # Expected: -15
    print(eval_expression("0 / 5"))              # Expected: 0.0

    try:
        eval_expression("5 / 0")
    except ZeroDivisionError as e:
        print(f"Caught expected error: {e}")

    try:
        eval_expression("(3 + 4) * (2 - 1)")   # Expected: 7
        print(eval_expression((3 + 4) * (2 - 1))) 
    except TypeError:
        print("Note: Only string expressions are accepted")

